	public String dept, begin, end, ClassNo[], student_no[], Oid[];

	public String search() {
		StringBuilder sb = new StringBuilder("SELECT e.*, d.name FROM Enroll_snato e, CODE_DEPT d WHERE d.id=e.depts ");

		if (!begin.trim().equals(""))
			sb.append("AND sendate>='" + begin + "'");
		if (!end.trim().equals(""))
			sb.append(" AND sendate<='" + end + "'");
		if (!dept.trim().equals("")) {
			sb.append(" AND depts='" + dept + "'");
		}

		// System.out.println(sb);
		request.setAttribute("stds", df.sqlGet(sb.toString()));

		return SUCCESS;
	}

