	public String add() {
		SimpleDateFormat sf = new SimpleDateFormat("yyyy-MM-dd");
		StringBuilder errMsg = new StringBuilder();
		for (int i = 0; i < Oid.length; i++) {

			if (Oid[i].equals(""))
				continue;

			if (student_no[i].trim().length() < 8 || ClassNo[i].indexOf(",") == -1)
				continue;

			errMsg.append("<br>" + student_no[i] + ",");
			System.out.println("SELECT*FROM Enroll_snato WHERE Oid=" + Oid[i]);
			Map std = df.sqlGetMap("SELECT*FROM Enroll_snato WHERE Oid=" + Oid[i]);

			stmd s = new stmd();
			try {
				s.setBirthCounty(String.valueOf(std.get("nation")));
			} catch (Exception e) {
				errMsg.append("國籍錯誤");
			}
			try {
				s.setBirthday(sf.parse(std.get("bdate").toString()));
			} catch (Exception e) {
				errMsg.append("生日錯誤");
			}
			try {
				s.setCellPhone(std.get("cell").toString());
			} catch (Exception e) {
				errMsg.append("手機錯誤");
			}
			try {
				s.setTelephone(std.get("tel_tw").toString());
			} catch (Exception e) {
				errMsg.append("在台電話錯誤");
			}
			try {
				s.setEmail(std.get("email").toString());
			} catch (Exception e) {
				errMsg.append("電子郵件錯誤");
			}
			try {
				s.setCurrAddr(std.get("addr_m").toString());
			} catch (Exception e) {
				errMsg.append("地址錯誤");
			}
			try {
				s.setPermAddr(std.get("addr_h").toString());
			} catch (Exception e) {
				errMsg.append("戶籍地址錯誤");
			}
			try {
				s.setIdno(std.get("passport").toString());
			} catch (Exception e) {
				errMsg.append("戶籍地址錯誤");
			}
			try {
				s.setParentName(std.get("emergency_c").toString());
			} catch (Exception e) {
				errMsg.append("連絡人錯誤");
			}
			try {
				s.setStudentName(std.get("cname").toString());
			} catch (Exception e) {
				try {
					s.setStudentName(std.get("ename").toString());
				} catch (Exception ex) {
					errMsg.append("英文名錯誤");
				}
				errMsg.append("中文名錯誤");
			}
			try {
				s.setStudentEname(std.get("ename").toString());
			} catch (Exception e) {
				errMsg.append("英文名錯誤");
			}
			try {
				s.setDepartClass(ClassNo[i].substring(0, ClassNo[i].indexOf(",")));
			} catch (Exception e) {
				errMsg.append("班級錯誤");
			}
			try {
				s.setStudentNo(student_no[i]);
			} catch (Exception e) {
				errMsg.append("學號錯誤");
			}

			// try {s.setDepartClass(ClassNo[i]);}catch(Exception e) {errMsg.append("錯誤");}

			try {
				df.update(s);
				errMsg.append(", 學籍資料已建立");
				df.exSql("UPDATE Enroll_snato SET depart_class='" + ClassNo[i] + "', student_no='" + student_no[i]
						+ "' WHERE Oid=" + Oid[i]);
			} catch (Exception e) {
				// e.printStackTrace();
				errMsg.append(", 無法建立");
			}

		}
		Message msg = new Message();
		// errMsg.append("<br>相關資料將於隔日自動完成");
		msg.setError(errMsg.toString());
		this.savMessage(msg);
		return search();
	}

	public String saveFile() {

		String tmp_path = getContext().getRealPath("/tmp");// 本機暫存目錄
		String target = "host_runtime";
		Message msg = new Message();
		StringBuilder sb = new StringBuilder("SELECT*FROM Enroll_snato WHERE Oid IN(");
		for (int i = 0; i < Oid.length; i++) {
			if (!Oid[i].equals("")) {
				sb.append(Oid[i] + ",");
			}
		}
		sb.delete(sb.length() - 1, sb.length());
		sb.append(")");

		// File zipFile;
		List<Map> stds;
		String errMsg = "";
		try {
			stds = df.sqlGet(sb.toString());
			if (getContext().getAttribute("isServer").equals("0")) {// 測試的情況
				target = "host_debug";
				tmp_path = tmp_path.replace("\\", "/");
			}
			File file6[];
			for (int i = 0; i < stds.size(); i++) {
				for (int j = 1; j <= 6; j++) {
					saveLocal(String.valueOf(stds.get(i).get("f" + j)), tmp_path);

				}
				file6 = new File[6];
				for (int j = 0; j < 6; j++) {

					file6[j] = new File(getContext().getRealPath("/tmp") + "/" + stds.get(i).get("f" + (j + 1)));

				}
				// errMsg+=saveZip(tmp_path, getContext().getRealPath("/tmp"
				// )+"/"+stds.get(i).get("passport")+".zip", file6);

				// zipFileBuffer(getContext().getRealPath("/tmp"
				// )+"/"+stds.get(i).get("passport")+".zip", file6);
				zipFileChannel(getContext().getRealPath("/tmp") + "/" + stds.get(i).get("passport") + ".zip", file6);
			}
		} catch (Exception e) {
			e.printStackTrace();
			msg.setError(e.getMessage());
			this.savMessage(msg);
			// return search();
		}

		Date d = new Date();

		try {
			/*
			 * //一次性處理全部zip File file = new File(getContext().getRealPath("/tmp" )); File[]
			 * files = file.listFiles(); File zipFile = new
			 * File(getContext().getRealPath("/tmp" )+"/"+d.getTime()+".zip"); InputStream
			 * input = null; ZipOutputStream zipOut = new ZipOutputStream(new
			 * FileOutputStream(zipFile)); zipOut.setComment("hello");
			 * if(file.isDirectory()){
			 * 
			 * for(int i = 0; i < files.length; ++i){
			 * //System.out.println(files[i].getName());
			 * if(files[i].getName().indexOf("null")>=0 ) { files[i].delete(); continue; }
			 * input = new FileInputStream(files[i]); zipOut.putNextEntry(new
			 * ZipEntry(files[i].getName()));
			 * 
			 * int temp = 0;
			 * 
			 * while((temp = input.read()) != -1){ zipOut.write(temp); }
			 * 
			 * input.close(); files[i].delete();//刪除已打包ZIP
			 * 
			 * } } zipOut.close();
			 */

			File file = new File(getContext().getRealPath("/tmp"));
			File[] files = file.listFiles();

			File zipFile = new File(getContext().getRealPath("/tmp") + "/" + d.getTime() + ".zip");
			try (ZipOutputStream zipOut = new ZipOutputStream(new FileOutputStream(zipFile));

					WritableByteChannel writableByteChannel = Channels.newChannel(zipOut)) {

				for (int i = 0; i < files.length; i++) {
					if (files[i].getName().indexOf("null") != -1) {
						files[i].delete();
						continue;
					}
					try (FileChannel fileChannel = new FileInputStream(files[i].getPath()).getChannel()) {
						zipOut.putNextEntry(new ZipEntry(files[i].getName()));
						fileChannel.transferTo(0, files[i].length(), writableByteChannel);
					}
					files[i].delete();
				}

			} catch (Exception e) {
				e.printStackTrace();
			}

		} catch (Exception e) {
			e.printStackTrace();
		}

		if (errMsg.length() >= 0) {
			msg.setError(errMsg);
			this.savMessage(msg);
		}

		// 產生下載檔案
		try {

			String downloadFilename = d.getTime() + ".zip";
			downloadFilename = URLEncoder.encode(downloadFilename, "UTF-8");

			File file = new File(getContext().getRealPath("/tmp") + "/" + d.getTime() + ".zip");
			if (file.exists()) {

				response.setContentLength((int) file.length());
				response.setHeader("Content-Disposition", "attachment;filename=" + downloadFilename);
				response.setContentType("application/octet-stream");

				FileInputStream fileInputStream = new FileInputStream(file);
				BufferedInputStream bufferedInputStream = new BufferedInputStream(fileInputStream);
				byte[] b = new byte[bufferedInputStream.available()];
				bufferedInputStream.read(b);
				OutputStream outputStream = response.getOutputStream();
				outputStream.write(b);

				bufferedInputStream.close();
				outputStream.flush();
				outputStream.close();
				// 刪除
				file.delete();
			}

			return null;
		} catch (Exception e) {
			errMsg += e.getMessage();
			msg.setError(errMsg);
			this.savMessage(msg);
			return search();
		}

	}

