	/***
	 * 壓縮 - 最舊的版本 * *
	 * 
	 * @param tmp_path
	 * @param zip_path
	 * @param files
	 * @return
	 * @throws IOException
	 */
	private String saveZip(String tmp_path, String zip_path, File[] files) throws IOException {
		StringBuilder errMsg = new StringBuilder("");

		// File file = new File(tmp_path);
		File zipFile = new File(zip_path);
		InputStream input = null;
		ZipOutputStream zipOut = new ZipOutputStream(new FileOutputStream(zipFile));
		// zipOut.setComment("hello");

		for (int i = 0; i < files.length; ++i) {
			System.out.println(files[i].getName());
			if (files[i].getName().indexOf("null") != -1) {
				files[i].delete();
				continue;
			}
			try {
				input = new FileInputStream(files[i]);
				// zipOut.putNextEntry(new ZipEntry(file.getName()+ File.separator +
				// files[i].getName()));
				zipOut.putNextEntry(new ZipEntry(files[i].getName()));
				int temp = 0;
				while ((temp = input.read()) != -1) {
					zipOut.write(temp);
				}
				input.close();
				files[i].delete();
			} catch (Exception e) {
				errMsg.append(e.getMessage() + "<br>");
			}

		}

		zipOut.close();
		return errMsg.toString();
	}

	/***
	 * 壓縮 - 第2版
	 * 
	 * @param zip_path
	 * @param files
	 */
	public static void zipFileBuffer(String zip_path, File[] files) {
		File zipFile = new File(zip_path);
		try (ZipOutputStream zipOut = new ZipOutputStream(new FileOutputStream(zipFile));
				BufferedOutputStream bufferedOutputStream = new BufferedOutputStream(zipOut)) {
			// 开始时间 long beginTime = System.currentTimeMillis();
			for (int i = 0; i < files.length; i++) {
				try (BufferedInputStream bufferedInputStream = new BufferedInputStream(
						new FileInputStream(files[i].getPath()))) {
					zipOut.putNextEntry(new ZipEntry(zip_path));
					int temp = 0;
					while ((temp = bufferedInputStream.read()) != -1) {
						bufferedOutputStream.write(temp);
					}
				}
			}
			// printInfo(beginTime);
		} catch (Exception e) {
			e.printStackTrace();
		}
	}

	/***
	 * 最快速的壓縮方式
	 * 
	 * @param zip_path
	 * @param files
	 */
	public static void zipFileChannel(String zip_path, File[] files) {
		File zipFile = new File(zip_path);
		try (ZipOutputStream zipOut = new ZipOutputStream(new FileOutputStream(zipFile));

				WritableByteChannel writableByteChannel = Channels.newChannel(zipOut)) {

			for (int i = 0; i < files.length; i++) {
				if (files[i].getName().indexOf("null") != -1) {
					files[i].delete();
					continue;
				}
				try (FileChannel fileChannel = new FileInputStream(files[i].getPath()).getChannel()) {
					zipOut.putNextEntry(new ZipEntry(files[i].getName()));
					fileChannel.transferTo(0, files[i].length(), writableByteChannel);
				}
				files[i].delete();
			}

		} catch (Exception e) {
			e.printStackTrace();
		}

	}

	private void saveLocal(String fileName, String tmp_path) throws IOException {

		File dst = new File(tmp_path);// 暫存資料夾 TBTB
		if (!dst.exists())
			dst.mkdir();

		String path = "enroll";
		String host = ((Map) getContext().getAttribute("FtpMain")).get("host_runtime").toString();
		if (getContext().getAttribute("isServer").equals("0")) {
			host = ((Map) getContext().getAttribute("FtpMain")).get("host_debug").toString();
		}
		FtpClient ftp = new FtpClient(host, "CIS", "cust!@#", "", "");

		System.out.println("FTP: " + path + "/" + fileName + ",下載到:" + tmp_path);
		ftp.connect();
		ftp.setBinaryTransfer(true);
		ftp.get(path + "/" + fileName, tmp_path + "/" + fileName, false);
		ftp.disconnect();

		// return filePath;
	}

